#!/usr/bin/env node
// wugweb-voice: build.mjs
// Compiles the skill into portable files so agents other than Claude can load it.
//
//   node scripts/build.mjs           write the generated files
//   node scripts/build.mjs --check   exit 1 if any generated file is stale
//
// Sources: SKILL.md, references/*.md, metadata.json. Never edit the outputs.
// The skill name is read from SKILL.md, so a rename needs no change here.
//
// Two reference files are left out of every generated file: corpus.md (it points
// at the owner's private writing) and tooling.md (Claude-only tool wiring). The
// single-file artifacts therefore carry the method, not the sample ledger.

import { readFileSync, writeFileSync, mkdirSync, existsSync, readdirSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..');
const read = (p) => readFileSync(join(ROOT, p), 'utf8');

// Reference files that go into the portable build, in reading order. corpus.md
// and tooling.md are deliberately excluded.
export const INCLUDED = ['voice.md', 'modes.md', 'words.md', 'handoff.md', 'blind-test.md'];

const meta = existsSync(join(ROOT, 'metadata.json')) ? JSON.parse(read('metadata.json')) : null;
const skill = read('SKILL.md');
const front = skill.match(/^---\n([\s\S]*?)\n---\n/);
if (!front) throw new Error('SKILL.md has no frontmatter');
const body = skill.slice(front[0].length).trim();
const name = front[1].match(/^name:\s*(\S+)\s*$/m)?.[1];
const descRaw = front[1].match(/^description:\s*(".*")\s*$/m)?.[1];
if (!name || !descRaw) throw new Error('SKILL.md frontmatter needs name and a double-quoted description');
const description = JSON.parse(descRaw);
const version = (front[1].match(/version:\s*"([^"]+)"/) || [])[1] || (meta && meta.version) || 'unknown';
const org = (meta && meta.organization) || 'Wugweb';
const date = (meta && meta.date) || '';
const abstract = (meta && meta.abstract) || description;

// Push headings one level down, leaving fenced code alone.
const demote = (md) => md.split(/(```[\s\S]*?```)/).map((p, i) => (i % 2 ? p : p.replace(/^(#{1,5}) /gm, '#$1 '))).join('');
const banner = '<!-- Generated by scripts/build.mjs. Do not edit by hand. -->';

const includedOnDisk = INCLUDED.filter((f) => existsSync(join(ROOT, 'references', f)));

// AGENTS.md: the whole skill in one file, for any agent that reads plain instructions.
const agents = [
  banner,
  '',
  body.replace(/^# .*$/m, `# ${name}\n\n**Version ${version}**${org ? ` · ${org}` : ''}${date ? ` · ${date}` : ''}\n\n${abstract}`),
  '',
  '---',
  '',
  '# Reference material',
  '',
  "The sections below are the skill's `references/` files, included so this document works alone. The calibration ledger (`corpus.md`) and the tool wiring (`tooling.md`) are left out on purpose: the ledger points at private writing, and the wiring is Claude-only.",
  '',
  ...includedOnDisk.map((f) => `<!-- references/${f} -->\n` + demote(read(`references/${f}`).trim()) + '\n'),
].join('\n');

// Cursor rule. Voice applies to any visible copy, so it attaches by description,
// not always-on, and the globs cover the copy files and the skill folder.
const cursor = [
  '---',
  `description: ${JSON.stringify(description)}`,
  'globs: ["**/*.md", "**/*.mdx", "**/*.astro", "**/*.html", "**/skills/' + name + '/**"]',
  'alwaysApply: false',
  '---',
  '',
  banner,
  '',
  body,
  '',
].join('\n');

// Custom GPT or ChatGPT project instructions.
const chatgpt = [
  banner,
  '',
  '# Instructions for a custom GPT or project',
  '',
  'Paste the block below into the instructions field. Upload `AGENTS.md` from this skill as a knowledge file.',
  '',
  '```',
  'You hold the one Wugweb voice, which is also the owner\'s voice, and you run the',
  'voice check on visible Wugweb copy, using the method in the uploaded file',
  'AGENTS.md. Read AGENTS.md before any task about checking the voice, making text',
  'sound like Wugweb or the owner, rewriting in the voice, or saying whether a',
  'draft is on voice.',
  '',
  'Always:',
  '- Apply the fixed owner rules: British English, sentence case, no em or en',
  '  dashes, never invent a number quote or fact, no filler words.',
  '- Say plainly that the voice is not calibrated while no approved samples exist,',
  '  and give confidence as low. A pass means "not detected", never "proven".',
  '- List every number, quote and scope word to trace before and after a rewrite.',
  '- Show any change as current then proposed. Keep client quotes and on-screen',
  '  terms unchanged.',
  '- Raise a candidate word or rule as a question for the owner, never as a flag.',
  '',
  'Never:',
  '- Invent the voice from helper advice, general good-writing tips, or examples',
  '  the owner has not approved.',
  '- Guess personality, beliefs or decision style from the writing.',
  '- Invent or fill a missing number, quote or fact.',
  '- Change format, length, SEO or positioning rules, or publish anything.',
  '',
  'If you can run code, run scripts/check.mjs on the draft for the mechanical',
  'checks. If you cannot, apply those checks by reading the text and label the',
  'result a manual check.',
  '```',
  '',
].join('\n');

// Display settings for Codex and the ChatGPT desktop app. Other agents ignore it.
const title = body.match(/^# (.+)$/m)?.[1] ?? name;
const openai = [
  '# Generated by scripts/build.mjs. Do not edit by hand.',
  '# Display settings for Codex and the ChatGPT desktop app. Other agents ignore this file.',
  'interface:',
  `  display_name: ${JSON.stringify(title)}`,
  '  short_description: "Hold the Wugweb voice and run the voice check"',
  '  default_prompt: "Voice check this draft against wugweb-voice and show the findings."',
  'policy:',
  '  allow_implicit_invocation: true',
  '',
].join('\n');

// export/wugweb-voice.md: the single-file paste, kept for continuity. Same body
// and references as AGENTS.md, without the metadata header.
const exportFile = [
  `<!-- wugweb-voice ${version}. Built by scripts/build.mjs. Do not edit; edit the source files. -->`,
  '',
  body,
  ...includedOnDisk.map((f) => '\n---\n\n' + `<!-- references/${f} -->\n\n` + read(`references/${f}`).trim()),
].join('\n') + '\n';

const outputs = {
  'AGENTS.md': agents,
  [`adapters/cursor/${name}.mdc`]: cursor,
  'adapters/chatgpt/instructions.md': chatgpt,
  'agents/openai.yaml': openai,
  'export/wugweb-voice.md': exportFile,
};

export function build() {
  for (const [path, content] of Object.entries(outputs)) {
    const full = join(ROOT, path);
    mkdirSync(dirname(full), { recursive: true });
    writeFileSync(full, content);
  }
  return exportFile;
}

const isMain = process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1];
if (isMain) {
  const check = process.argv.includes('--check');
  let stale = 0;
  for (const [path, content] of Object.entries(outputs)) {
    const full = join(ROOT, path);
    const current = existsSync(full) ? readFileSync(full, 'utf8') : null;
    if (check) {
      const ok = current === content;
      console.log(`${ok ? 'fresh' : 'STALE'}  ${path}`);
      if (!ok) stale++;
    } else {
      mkdirSync(dirname(full), { recursive: true });
      writeFileSync(full, content);
      console.log(`wrote  ${path}`);
    }
  }
  process.exit(stale ? 1 : 0);
}
